type BaseProgrammeMessageKey = (typeof rows)[number][0];

const programmeMessageAliases = {
  "A two-step route": { target: "A 2-step route" },
  "An unexpected offer": { target: "An unexpected offer appears" },
  "At the saved early signal": { target: "When the early signal appears" },
  "Boundary category": { target: "Your boundary" },
  "Card style": { target: "Support card" },
  "Difficult-day response": { target: "Difficult-day version" },
  "Early signal category": { target: "Where you may notice it first" },
  "Every 7 days": { target: "Every {days} days", values: { days: 7 } },
  "Every 14 days": { target: "Every {days} days", values: { days: 14 } },
  "Every 30 days": { target: "Every {days} days", values: { days: 30 } },
  "Execution method": { target: "How you will put it in place" },
  "Exit action": { target: "Your exit action" },
  "Fallback strategy": { target: "Fallback response" },
  "Goal style": { target: "Your 7-day approach" },
  "I should choose another method": { target: "Choose another method" },
  "Licence / regulatory status": { target: "Licence and regulatory status" },
  "Licensing or regulatory status": { target: "Licence and regulatory status" },
  "Material term": { target: "Offer term to check" },
  "One or two layers": { target: "Your friction layers" },
  "Operator identity": { target: "Who operates the casino" },
  "Pause rule": { target: "Your pause rule" },
  "Possible bypass": { target: "What could undo it" },
  "Response strategy": { target: "First response" },
  "Scenario": { target: "Practice moment" },
  "Setup check": { target: "What it needs next" },
  "Seven-day direction": { target: "Your direction" },
  "Three checks": { target: "Your 3 checks" },
  "Unclear terms": { target: "Terms remain unclear" },
  "Use the support route": { target: "Use a support route" },
  "Wait ten minutes": { target: "Wait 10 minutes" },
  "Wait twenty minutes": { target: "Wait 20 minutes" },
  "When X, I can Y": { target: "When this happens, I can take the next step" },
  "When it starts": { target: "When it acts" },
} as const satisfies Readonly<Record<string, {
  target: BaseProgrammeMessageKey;
  values?: Readonly<Record<string, string | number>>;
}>>;

type ProgrammeMessageAliasKey = keyof typeof programmeMessageAliases;
export type ProgrammeMessageKey = BaseProgrammeMessageKey | ProgrammeMessageAliasKey;

const translationIndex = {
  "en-GB": 0,
  "de-DE": 1,
  "es-ES": 2,
  "sv-SE": 3,
  "da-DK": 4,
  "el-GR": 5,
  "it-IT": 6,
  "pt-PT": 7,
  "nl-NL": 8,
  "fi-FI": 9,
  "nb-NO": 10,
} as const satisfies Record<ProgrammeLocale, number>;

const rowByKey = new Map<string, ProgrammeMessageRow>();
for (const row of rows) {
  if (rowByKey.has(row[0])) throw new Error(`Duplicate Programme message: ${row[0]}`);
  rowByKey.set(row[0], row);
}

export const PROGRAMME_MESSAGE_KEYS: readonly ProgrammeMessageKey[] = [
  ...rows.map((row) => row[0]),
  ...Object.keys(programmeMessageAliases) as ProgrammeMessageAliasKey[],
];

export function programmeText(
  locale: ProgrammeLocale,
  key: ProgrammeMessageKey,
  values: Readonly<Record<string, string | number>> = {},
) {
  const directRow = rowByKey.get(key);
  const alias = programmeMessageAliases[key as ProgrammeMessageAliasKey];
  const targetRow = alias ? rowByKey.get(alias.target) : undefined;
  if (!directRow && !targetRow) throw new Error(`Missing Programme message: ${key}`);
  const value = directRow
    ? directRow[translationIndex[locale]]
    : locale === "en-GB"
      ? key
      : targetRow![translationIndex[locale]];
  const aliasValues = alias && "values" in alias ? alias.values : {};
  return Object.entries({ ...aliasValues, ...values }).reduce(
    (result, [name, replacement]) => result.replaceAll(`{${name}}`, String(replacement)),
    value,
  );
}

export function programmeCatalogueEntries(locale: ProgrammeLocale) {
  return PROGRAMME_MESSAGE_KEYS.map((key) => ({ key, value: programmeText(locale, key) }));
}

export function programmeMissionCopy(locale: ProgrammeLocale, missionNumber: number) {
  return currentProgrammeCopy(locale).missions[missionNumber - 1] ?? currentProgrammeCopy(locale).missions[0];
}
